import {once} from 'node:events';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {connectClient, startEngineWith, stopEngines} from './wsTestSupport.js';

// @spec-file specs/hal-engine-conversation-list/spec.md#37
afterEach(stopEngines);

it('returns only the authenticated user’s summaries over the socket', async () => {
  const store = new InMemorySessionStore();
  store.create('owned', 'u1');
  store.create('private', 'u2');
  const {url, hal} = await startEngineWith({sessionStore: store});
  const client = connectClient(url);
  const frames: unknown[] = [];
  let expected: unknown;
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as {type: string};
      if (frame.type !== 'connected') {
        if (frame.type === 'pong') return resolve();
        frames.push(frame);
        return;
      }
      expected = JSON.parse(JSON.stringify({type: 'session_list', sessions: store.listFor('u1')}));
      client.send(JSON.stringify({type: 'list_sessions', userId: 'u2'}));
      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    });
  });
  const closed = Promise.all([...hal.wss.clients].map(socket => once(socket, 'close')));
  client.close();
  await closed;
  expect(frames).toEqual([expected]);
});
import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = VALIDATORS.get(message.type);
  if (validator === undefined) return {valid: false, error: `Unknown message type: ${message.type}`};
  return validator(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function isValidListLimit(limit: unknown): boolean {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
}

function validateListSessions(message: Record<string, unknown>): ValidationResult {
  const result: ListSessionsMessage = {type: 'list_sessions'};
  if (message.limit !== undefined && !isValidListLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  if (typeof message.limit === 'number') result.limit = message.limit;
  if (message.before === undefined) return {valid: true, data: result};

  if (typeof message.before !== 'object' || message.before === null) {
    return {valid: false, error: 'list_sessions before must be a cursor object'};
  }
  const {sessionId, updatedAt} = message.before as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > 128) {
    return {valid: false, error: 'list_sessions before.sessionId must be 1–128 characters'};
  }
  if (
    (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') ||
    !Number.isFinite(new Date(updatedAt).getTime())
  ) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
  }
  result.before = {sessionId, updatedAt};
  return {valid: true, data: result};
}

const VALIDATORS = new Map<string, (message: Record<string, unknown>) => ValidationResult>([
  ['user_message', validateUserMessage],
  ['list_sessions', validateListSessions],
  ['ping', validatePingMessage],
]);

